// Generated by Cypress Author — 2026-04-27
describe('Dossier — ajout', () => {
    beforeEach(() => {
        cy.login()
    });

    // Generated by Cypress Author — 2026-10-09
    describe('Dossier — service instructeur', () => {
        beforeEach(() => {
            cy.login()
            cy.intercept('GET', '**/api/groupements/search*', [{
                libelle: 'Service homonyme',
                type: { libelle: 'Service instructeur' },
            }]).as('groupements')
            cy.intercept('GET', '**/api/2.0/adresse/get_communes*', {
                response: [{ LIBELLE_COMMUNE: 'Service homonyme' }],
            }).as('communes')
            cy.visit('/dossier/ajouter')
            cy.wait(['@groupements', '@communes'])
            cy.get('#dossier_type').select('1')
            cy.get('#dossier_nature').select('1')
        })

        it('Suggestions homonymes, saisie libre et effacement → libellé et type restent cohérents', () => {
            cy.get('#field-serviceInstructeur .ts-control').click()
            cy.get('#field-serviceInstructeur [data-value="servInstGrp:Service homonyme"]').click()
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstGrp')

            cy.get('#field-serviceInstructeur .ts-control input').type('{backspace}')
            cy.get('#dossier_serviceInstructeur').should('have.value', '')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', '')
            cy.get('#field-serviceInstructeur .ts-control input').type('Service homonyme')
            cy.get('#field-serviceInstructeur [data-value="servInstCommune:Service homonyme"]').click()
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstCommune')

            cy.get('#field-serviceInstructeur .ts-control').click()
            cy.get('#field-serviceInstructeur .ts-control input').type('{backspace}Service libre')
            cy.contains('#field-serviceInstructeur .create', 'Ajouter').click()
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service libre')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', '')
        })

        it('Service sans type resélectionné → le type est enregistré puis conservé en modification', () => {
            cy.get('#dossier_dateInsert').type(new Date().toISOString().split('T')[0])
            cy.get('#dossier_objet').type(`Service instructeur ${Date.now()}`)
            cy.get('#field-serviceInstructeur .ts-control input').type('Service homonyme')
            cy.contains('#field-serviceInstructeur .create', 'Ajouter').click()
            cy.contains('button', 'Créer le dossier').click()
            cy.url().should('match', /\/dossier\/\d+/)
            cy.contains('Modifier le dossier').click()
            cy.wait(['@groupements', '@communes'])
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', '')
            cy.get('#field-serviceInstructeur .ts-control .item').should('contain', 'Service homonyme')
            cy.get('#field-serviceInstructeur .ts-control').click()
            cy.get('#field-serviceInstructeur .ts-control input').type('{backspace}Service homonyme')
            cy.get('#field-serviceInstructeur [data-value="servInstCommune:Service homonyme"]').click()
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstCommune')
            cy.contains('button', 'Sauvegarder').click()
            cy.url().should('match', /\/dossier\/\d+/)
            cy.contains('Modifier le dossier').click()
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstCommune')
            cy.contains('button', 'Sauvegarder').click()
            cy.url().should('match', /\/dossier\/\d+/)
            cy.contains('Modifier le dossier').click()
            cy.get('#dossier_serviceInstructeur').should('have.value', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstCommune')
        })

        it('Commune avec un ancien type groupement → libellé visible, type rectifiable et effacement sauvegardé', () => {
            cy.get('#dossier_dateInsert').type(new Date().toISOString().split('T')[0])
            cy.get('#dossier_objet').type(`Commune historique ${Date.now()}`)
            // Reproduire le couple incohérent stocké avant la remise en place du type.
            cy.get('#dossier_serviceInstructeur').invoke('val', 'Commune historique')
            cy.get('#dossier_typeServiceInstructeur').invoke('val', 'servInstGrp')
            cy.contains('button', 'Créer le dossier').click()
            cy.contains('Modifier le dossier').click()
            cy.wait(['@groupements', '@communes'])
            cy.get('#field-serviceInstructeur .ts-control .item').should('contain', 'Commune historique')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstGrp')

            cy.get('#field-serviceInstructeur .ts-control').click()
            cy.get('#field-serviceInstructeur .ts-control input').type('{backspace}Service homonyme')
            cy.get('#field-serviceInstructeur [data-value="servInstCommune:Service homonyme"]').click()
            cy.contains('button', 'Sauvegarder').click()
            cy.contains('Modifier le dossier').click()
            cy.get('#field-serviceInstructeur .ts-control .item').should('contain', 'Service homonyme')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', 'servInstCommune')

            cy.get('#field-serviceInstructeur .ts-control').click()
            cy.get('#field-serviceInstructeur .ts-control input').type('{backspace}')
            cy.get('#dossier_serviceInstructeur').should('have.value', '')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', '')
            cy.contains('button', 'Sauvegarder').click()
            cy.contains('Modifier le dossier').click()
            cy.get('#field-serviceInstructeur .ts-control .item').should('not.exist')
            cy.get('#dossier_serviceInstructeur').should('have.value', '')
            cy.get('#dossier_typeServiceInstructeur').should('have.value', '')
        })
    })

    it('Formulaire valide → dossier créé avec les bonnes valeurs', () => {
        const timestamp = Date.now()
        const objet = `Dossier Test ${timestamp}`
        const today = new Date().toISOString().split('T')[0]

        cy.visit('/dossier/ajouter')
        // Symfony form fields: id pattern is dossier_{fieldName}
        cy.get('#dossier_type').select('1')
        cy.get('#dossier_nature').select('1')
        // Utiliser .type() (pas .invoke('val')) pour déclencher les événements browser
        cy.get('#dossier_dateInsert').type(today)
        cy.get('#dossier_objet').type(objet)

        cy.contains('button', 'Créer le dossier').click()

        // Vérifier la redirection vers la fiche du dossier (URL pattern: /dossier/{id})
        cy.url({ timeout: 10000 }).should('match', /\/dossier\/\d+/)

        // Fiche dossier: les valeurs sont affichées dans des .right.value
        cy.contains('Étude').should('exist')
        cy.contains('Permis de construire (PC)').should('exist')
        cy.contains(objet).should('exist')
    });
});
